mapper.select:
SELECT aa.archive_attachment_id, aa.document_name, nvl(aa.source_id,aa.archive_attachment_id) as source_id, aa.project_id, (select project_number from prj_project pp where pp.project_id = aa.project_id) as project_number, (select s.description from jc_archive ja,sys_user s where ja.archivist_id = s.user_id and ja.uuid = aa.uuid and ja.project_id = aa.project_id and ja.archive_type = aa.archive_type) as archivist_id_n, (select ja.archive_number from jc_archive ja where ja.uuid = aa.uuid and ja.project_id = aa.project_id and ja.archive_type = aa.archive_type) as archive_number, (select ja.archive_name from jc_archive ja where ja.uuid = aa.uuid and ja.project_id = aa.project_id and ja.archive_type = aa.archive_type) as archive_name, aa.uuid, nvl(aa.source_type,'JC_ARCHIVE_ATTACHMENT') as source_type, ( SELECT wm_concat( fa.file_name ) FROM fnd_atm_attachment fa, fnd_atm_attachment_multi fam WHERE fa.attachment_id = fam.attachment_id AND fam.table_name = aa.source_type AND nvl(aa.source_id,aa.archive_attachment_id) = fam.table_pk_value ) AS file_name, aa.page_number, aa.quantity, aa.file_date, aa.archive_type, (select sc.meaning from sys_code_value_b_v sc where sc.code = 'JC_FILE_TYPE' and aa.archive_type = sc.code_value) archive_type_n, aa.description FROM jc_archive_attachment aa
1=1 and aa.project_id = #{projectId}
and aa.archive_type = #{archiveType}
and aa.uuid = #{uuid}
